Add-Type -AssemblyName System.Drawing
function D($a,$b){ [math]::Abs($a.R-$b.R)+[math]::Abs($a.G-$b.G)+[math]::Abs($a.B-$b.B) }
function RowRuns($bmp,$y,$x0,$x1,$ref,$th){ if(-not $ref){$ref=$bmp.GetPixel($x0,$y)}; if(-not $th){$th=40}; $runs=@(); $in=$false; $s=0; for($x=$x0;$x -le $x1;$x++){ $p=$bmp.GetPixel($x,$y); $ink=(D $p $ref) -gt $th; if($ink -and -not $in){$in=$true;$s=$x}; if(-not $ink -and $in){$in=$false;$runs+="$s-$($x-1)"} }; if($in){$runs+="$s-$x1"}; ($runs -join ' ') }
function ColRuns($bmp,$x,$y0,$y1,$ref,$th){ if(-not $ref){$ref=$bmp.GetPixel($x,$y0)}; if(-not $th){$th=40}; $runs=@(); $in=$false; $s=0; for($y=$y0;$y -le $y1;$y++){ $p=$bmp.GetPixel($x,$y); $ink=(D $p $ref) -gt $th; if($ink -and -not $in){$in=$true;$s=$y}; if(-not $ink -and $in){$in=$false;$runs+="$s-$($y-1)"} }; if($in){$runs+="$s-$y1"}; ($runs -join ' ') }
function InkBoxRows($bmp,$x0,$x1,$y0,$y1,$ref,$th){ if(-not $th){$th=40}; $rows=@(); for($y=$y0;$y -le $y1;$y++){ $any=$false; for($x=$x0;$x -le $x1;$x++){ if((D $bmp.GetPixel($x,$y) $ref) -gt $th){$any=$true;break} }; $rows+=[int]$any }; $runs=@(); $in=$false; for($i=0;$i -lt $rows.Count;$i++){ if($rows[$i] -and -not $in){$in=$true;$s=$i+$y0}; if(-not $rows[$i] -and $in){$in=$false;$runs+="$s-$($i+$y0-1)"} }; if($in){$runs+="$s-$y1"}; ($runs -join ' ') }
function InkBoxCols($bmp,$x0,$x1,$y0,$y1,$ref,$th){ if(-not $th){$th=40}; $cols=@(); for($x=$x0;$x -le $x1;$x++){ $any=$false; for($y=$y0;$y -le $y1;$y++){ if((D $bmp.GetPixel($x,$y) $ref) -gt $th){$any=$true;break} }; $cols+=[int]$any }; $runs=@(); $in=$false; for($i=0;$i -lt $cols.Count;$i++){ if($cols[$i] -and -not $in){$in=$true;$s=$i+$x0}; if(-not $cols[$i] -and $in){$in=$false;$runs+="$s-$($i+$x0-1)"} }; if($in){$runs+="$s-$x1"}; ($runs -join ' ') }
function Px($bmp,$x,$y){ $p=$bmp.GetPixel($x,$y); "($x,$y)=#{0:X2}{1:X2}{2:X2}" -f $p.R,$p.G,$p.B }
